--- index.html
+++ index.html
@@ -9,6 +9,91 @@
 @media(max-width:900px){body{overflow:auto}.app{grid-template-columns:1fr;height:auto;min-height:100dvh;padding:8px}.left{order:2}.right{order:3}.center{order:1;height:calc(100dvh - 16px);min-height:580px}.map{width:min(78vw,56vh);height:min(78vw,56vh)}.left,.right{max-height:none}.resources{grid-template-columns:repeat(4,1fr)}.unitlist{flex-direction:row}.log{height:70px}.brand h1{font-size:24px}}
 @media(max-width:560px){.app{gap:6px;padding:6px}.center{height:calc(100dvh - 12px);min-height:500px}.map{width:min(92vw,52vh);height:min(92vw,52vh)}.mapwrap{padding:5px}.left,.right{padding:10px}.resources{grid-template-columns:repeat(4,1fr)}.resource{padding:5px}.resource b{font-size:16px}.bottom{height:76px;padding:6px}.actions{gap:4px}.btn{padding:8px}.section{margin-top:7px}.brand{display:flex;justify-content:space-between}.era{margin:6px 0}}
 </style>
 </head>
-<body></body>
+<body>
+<div class="app">
+<aside class="panel left">
+  <div class="brand"><div><h1>Tiny Empires</h1><small>Age of Reeds</small></div></div>
+  <div class="era"><strong id="eraName">The Settling</strong><span class="turn">TURN <b id="turn">1</b></span></div>
+  <div class="resources">
+    <div class="resource"><b id="food">60</b><span>Food</span></div><div class="resource"><b id="wood">35</b><span>Wood</span></div>
+    <div class="resource"><b id="stone">20</b><span>Stone</span></div><div class="resource"><b id="gold">15</b><span>Gold</span></div>
+  </div>
+  <div class="section"><h3>Our People</h3><div class="unitlist" id="unitlist"></div></div>
+</aside>
+<main class="panel center">
+  <div class="mapwrap"><div class="map" id="map"></div></div>
+  <div class="bottom"><div class="status" id="status">Choose a unit or city.</div><div class="actions"><button class="btn secondary" id="waitBtn">Wait</button><button class="btn" id="endBtn">End Turn</button></div></div>
+  <div class="overlay" id="overlay"><div><h2 id="endTitle">Victory</h2><p id="endText">The rival empire has fallen.</p><button class="btn" id="againBtn">Play Again</button></div></div>
+</main>
+<aside class="panel right">
+  <h2>Your Capital</h2><div class="cityinfo"><h3 id="cityName">Northhold</h3><span id="popText">Population 2</span><div class="bar"><i id="popBar" style="width:30%"></i></div><small id="growthText">Next citizen in 4 turns</small></div>
+  <div class="section"><h3>City Production</h3><div class="buildgrid">
+    <div class="build" data-build="settler"><span>🏕️ <b>Settler</b><br><small>15 food · 10 gold</small></span><b>+</b></div>
+    <div class="build" data-build="warrior"><span>⚔️ <b>Warrior</b><br><small>10 food · 8 gold</small></span><b>+</b></div>
+  </div></div>
+  <div class="log" id="log"><p><span class="badge"></span>Northhold founded.</p><p><span class="badge red"></span>Red banner seen beyond the hills.</p></div>
+</aside>
+</div>
+<script>
+const N=10, mapEl=document.getElementById('map');
+let selected=null, turn=1, ended=false;
+let res={food:60,wood:35,stone:20,gold:15};
+const base=[['desert','grass','forest','grass','grass','grass','mountain','grass','forest','grass'],['grass','grass','forest','grass','hill','grass','mountain','grass','grass','forest'],['forest','grass','grass','grass','grass','grass','grass','forest','grass','grass'],['grass','grass','water','water','grass','grass','forest','forest','grass','grass'],['grass','forest','water','grass','grass','mountain','grass','grass','grass','forest'],['grass','grass','grass','grass','forest','mountain','grass','desert','desert','grass'],['forest','grass','grass','mountain','grass','grass','grass','desert','grass','grass'],['grass','forest','grass','grass','grass','forest','grass','grass','grass','mountain'],['grass','grass','desert','desert','grass','grass','grass','forest','forest','grass'],['forest','grass','grass','grass','grass','mountain','grass','grass','grass','grass']];
+let terrain=base.map(r=>r.map(t=>({type:t})));
+let cities=[{x:1,y:8,owner:'player',name:'Northhold',pop:2,growth:0},{x:8,y:1,owner:'enemy',name:'Red Fort',pop:2,growth:0}];
+let units=[{id:1,x:2,y:8,owner:'player',type:'settler',hp:4,moves:2},{id:2,x:1,y:7,owner:'player',type:'warrior',hp:5,moves:2},{id:3,x:7,y:2,owner:'enemy',type:'warrior',hp:5,moves:2},{id:4,x:8,y:2,owner:'enemy',type:'settler',hp:4,moves:2}];
+const icon={grass:'',forest:'♠',mountain:'▲',water:'≈',desert:'',hill:'⛰️'};
+function key(x,y){return y*N+x}function dist(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}
+function cityAt(x,y){return cities.find(c=>c.x===x&&c.y===y)}function unitAt(x,y){return units.find(u=>u.x===x&&u.y===y)}
+function log(s,enemy=false){let el=document.getElementById('log'),p=document.createElement('p');p.innerHTML=`<span class="badge ${enemy?'red':''}"></span>${s}`;el.prepend(p)}
+function render(){
+ mapEl.innerHTML='';
+ for(let y=0;y<N;y++)for(let x=0;x<N;x++){
+  let t=terrain[y][x].type,c=cityAt(x,y),u=unitAt(x,y),tile=document.createElement('div');tile.className=`tile ${t}`;tile.dataset.x=x;tile.dataset.y=y;
+  if(icon[t])tile.innerHTML=`<span class="terrain">${icon[t]}</span>`;
+  if(selected&&selected.x===x&&selected.y===y)tile.classList.add('selected');
+  if(selected&&selected.moves>0&&dist(selected,{x,y})===1&&!u&&!c&&t!=='water')tile.classList.add('moveable');
+  if(c){let e=document.createElement('div');e.className=`city ${c.owner}`;e.textContent=c.owner==='player'?'◆':'◆';tile.appendChild(e)}
+  if(u){let e=document.createElement('div');e.className=`mapunit ${u.owner}`;e.textContent=u.type==='warrior'?'⚔':'♟';e.title=`${u.type} HP ${u.hp}`;tile.appendChild(e)}
+  tile.onclick=()=>clickTile(x,y);mapEl.appendChild(tile);
+ }
+ let ul=document.getElementById('unitlist');ul.innerHTML='';
+ units.filter(u=>u.owner==='player').forEach(u=>{let d=document.createElement('div');d.className='unitcard'+(selected===u?' active':'');d.innerHTML=`<div class="token player">${u.type==='warrior'?'⚔':'♟'}</div><div><b>${u.type==='warrior'?'Warrior':'Settler'}</b><small>HP ${u.hp} · ${u.moves?'ready':'spent'}</small></div>`;d.onclick=()=>{selected=u;render();status()};ul.appendChild(d)});
+ document.getElementById('food').textContent=res.food;document.getElementById('wood').textContent=res.wood;document.getElementById('stone').textContent=res.stone;document.getElementById('gold').textContent=res.gold;document.getElementById('turn').textContent=turn;
+}
+function status(){let s='Choose a unit or city.';if(selected)s=`${selected.type==='warrior'?'Warrior':'Settler'} selected · ${selected.moves?'ready':'spent'}`;document.getElementById('status').textContent=s}
+function clickTile(x,y){
+ let u=unitAt(x,y),c=cityAt(x,y);
+ if(selected&&selected.owner==='player'&&selected.moves>0){
+  let enemy=u&&u.owner==='enemy',target=c&&c.owner==='enemy';
+  if(dist(selected,{x,y})===1&&(enemy||target||(!u&&!c&&terrain[y][x].type!=='water'))){
+   if(enemy||target){combat(selected,u||{...c,type:'city',hp:6,owner:'enemy'});return}
+   selected.x=x;selected.y=y;selected.moves--;log(`${selected.type==='warrior'?'Warrior':'Settler'} moved.`);render();status();return;
+  }
+ }
+ if(u&&u.owner==='player'){selected=u}else if(c&&c.owner==='player'){selected=c}else selected=null;
+ render();status()
+}
+function combat(attacker,defender){
+ let ah=attacker.type==='warrior'?5:4,dh=defender.type==='warrior'?5:4;
+ attacker.hp-=2;defender.hp-=attacker.type==='warrior'?3:2;
+ if(defender.hp<=0){if(defender.type==='city'||!defender.type){cities=cities.filter(c=>!(c.x===defender.x&&c.y===defender.y));log('Red banner defeated. City captured.',false)}else units=units.filter(u=>u!==defender);attacker.x=defender.x;attacker.y=defender.y}
+ attacker.moves--;
+ if(attacker.hp<=0)units=units.filter(u=>u!==attacker);
+ log(attacker.owner==='player'?`Your ${attacker.type==='warrior'?'warrior':'settler'} struck.`:'Enemy attacked.',attacker.owner==='enemy');render();status();checkEnd()
+}
+function endTurn(){if(ended)return;turn++;res.food+=18;res.wood+=8;res.stone+=4;res.gold+=5;
+ units.forEach(u=>u.moves=2);
+ cities.forEach(c=>{if(c.owner==='player'){c.growth++;if(c.growth>=4){c.growth=0;c.pop++}}});
+ ai();document.getElementById('eraName').textContent=turn<6?'The Settling':turn<12?'Age of Bronze':'Age of Reeds';render();status();checkEnd();log('New supplies delivered.')
+}
+function ai(){let enemies=units.filter(u=>u.owner==='enemy');for(let u of enemies){if(u.moves<=0)continue;let targets=units.filter(v=>v.owner==='player');let tc=targets.length?targets.sort((a,b)=>dist(u,a)-dist(u,b))[0]:cities.find(c=>c.owner==='player');if(!tc)continue;let dx=Math.sign(tc.x-u.x),dy=Math.sign(tc.y-u.y);let nx=u.x+((dx&&(!terrain[u.y]?.[u.x+dx]||terrain[u.y][u.x+dx].type!=='water'))?dx:0);let ny=u.y+(nx===u.x&&dy?dy:0);let occupant=unitAt(nx,ny);if(occupant&&occupant.owner==='player'&&dist(u,occupant)===1){combat(u,occupant)}else if(dist(u,tc)>1&&!unitAt(nx,ny)&&!cityAt(nx,ny)){u.x=nx;u.y=ny}u.moves--;}}
+function checkEnd(){let py=cities.some(c=>c.owner==='player'),ey=cities.some(c=>c.owner==='enemy');if(!ey){endGame(true)}else if(!py){endGame(false)}}
+function endGame(win){ended=true;let o=document.getElementById('overlay');document.getElementById('endTitle').textContent=win?'Victory':'Empire Fallen';document.getElementById('endText').textContent=win?'Northhold has united the valley.':'The rival banners now fly over the valley.';o.classList.add('show')}
+document.getElementById('endBtn').onclick=endTurn;document.getElementById('waitBtn').onclick=()=>{if(selected&&selected.owner==='player'){selected.moves=0;render();status()}};
+document.querySelectorAll('.build').forEach(b=>b.onclick=()=>{let type=b.dataset.build,cost=type==='settler'?{food:15,gold:10}:{food:10,gold:8};if(res.food>=cost.food&&res.gold>=cost.gold){res.food-=cost.food;res.gold-=cost.gold;let c=cities.find(c=>c.owner==='player');let spots=[[c.x+1,c.y],[c.x-1,c.y],[c.x,c.y+1],[c.x,c.y-1]];let spot=spots.find(([x,y])=>x>=0&&y>=0&&x<N&&y<N&&!unitAt(x,y)&&!cityAt(x,y)&&terrain[y][x].type!=='water');if(spot){units.push({id:Date.now(),x:spot[0],y:spot[1],owner:'player',type,moves:0,hp:type==='warrior'?5:4});log(`${type==='warrior'?'Warrior':'Settler'} produced.`);render()}else log('No open ground beside the capital.')}else log('Not enough resources.',true)});
+document.getElementById('againBtn').onclick=()=>location.reload();render();status();
+</script>
+</body>
 </html>
